/** The calendar date on a workspace's clock. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  const parts = new Intl.DateTimeFormat(\"en\", {
    timeZone, year: \"numeric\", month: \"2-digit\", day: \"2-digit\",
  }).formatToParts(parseIso(value));
  const part = (type: string) => parts.find((p) => p.type === type)"'!.value;
  return `${part("year")}-${part("month")}-${part("day")}`;
}

export function localHour(reference: Date, timeZone: string): number {
  return Number(new Intl.DateTimeFormat("en", {
    timeZone, hour: "2-digit", hourCycle: "h23",
  }).format(reference));
}

/** Shift a calendar date without applying elapsed-time arithmetic in its zone. */
export function shiftLocalDate(day: string, days: number): string {
  const date = new Date(day + "T12:00:00Z");
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}

/**
 * Resolve a wall-clock hour. Repeated hours use their first occurrence;
 * missing hours advance by the clock'"'s gap (Intl/Date compatible semantics).
 */
function localHourInstant(day: string, hour: number, timeZone: string): IsoTimestamp {
  const wall = Date.parse(day + \"T00:00:00Z\") + hour * HOUR_MS;
  const offsets = new Set<number>();
  for (const delta of [-48, -24, 0, 24, 48]) {
    const instant = new Date(wall + delta * HOUR_MS);
    const local = Date.parse(localDate(toIsoTimestamp(instant), timeZone) + \"T00:00:00Z\")
      + localHour(instant, timeZone) * HOUR_MS
      + instant.getUTCMinutes() * MINUTE_MS + instant.getUTCSeconds() * 1000;
    // Include minute offsets, e.g. Kathmandu and Lord Howe.
    const minute = Number(new Intl.DateTimeFormat(\"en\", {
      timeZone, minute: \"2-digit\",
    }).format(instant));
    offsets.add(local + (minute - instant.getUTCMinutes()) * MINUTE_MS - instant.getTime());
  }
  const candidates = [...offsets].map((offset) => wall - offset).sort((a, b) => a - b);
  const matching = candidates.filter((value) => {
    const date = new Date(value);
    return localDate(toIsoTimestamp(date), timeZone) === day && localHour(date, timeZone) === hour;
  });
  return toIsoTimestamp(new Date(matching[0] ?? candidates[candidates.length - 1]"'!));
}

export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  return localHourInstant(localDate(toIsoTimestamp(reference), timeZone), 0, timeZone);
}

export function startOfCalendarDay(day: string, timeZone: string): IsoTimestamp {
  return localHourInstant(day, 0, timeZone);
}

export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  return dueAt !== null && localDate(dueAt, timeZone) < localDate(toIsoTimestamp(reference), timeZone);
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

export function digestWindow(
  digestHourUtc: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHourUtc) || digestHourUtc < 0 || digestHourUtc > 23) {
    throw new RangeError(`digestHourUtc must be 0-23, got ${digestHourUtc}`);
  }
  let day = localDate(toIsoTimestamp(reference), timeZone);
  let end = localHourInstant(day, digestHourUtc, timeZone);
  if (parseIso(end).getTime() > reference.getTime()) {
    day = shiftLocalDate(day, -1);
    end = localHourInstant(day, digestHourUtc, timeZone);
  }
  return { start: localHourInstant(shiftLocalDate(day, -1), digestHourUtc, timeZone), end };
}
